export function zoneForDioceseSlug(slug: string | null | undefined): string {
  return (slug && DIOCESE_TIME_ZONES[slug]) || 'America/Toronto'
}

/** Format a UTC timestamp in a diocese's local zone, with a short zone label. */
export function formatInDioceseZone(
  value: string | Date,
  slug: string | null | undefined,
  locale = 'en-US',
): string {
  const tz = zoneForDioceseSlug(slug)
  const d = typeof value === 'string' ? new Date(value) : value
  if (isNaN(d.getTime())) return ''
  const main = new Intl.DateTimeFormat(locale, { timeZone: tz, dateStyle: 'full', timeStyle: 'short' }).format(d)
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: tz, timeZoneName: 'short' }).formatToParts(d)
  const abbr = parts.find((p) => p.type === 'timeZoneName')?.value ?? ''
  return abbr ? `${main} (${abbr})` : main
}
